function d(e){if(e.length<=160)return e;let o=e.slice(0,159);return`${o.slice(0,Math.max(o.lastIndexOf(" "),160/2)).replace(/[\s,;:.]+$/,"")}\u2026`}var n={hubHeading:"YouTubers on Mastodon: creators to follow, by topic",hubDescription:"Find YouTube creators who are on Mastodon, by topic: follow their Mastodon accounts and subscribe to their channels, no YouTube account needed.",hubIntro:["Many YouTube creators also post on Mastodon. These kits list them by topic, each with their Mastodon account and their YouTube channel, so you can follow one, subscribe to the other, or both.","A creator is listed when their YouTube channel and Mastodon account point to each other, they have been active recently, and they meet our listing rules: nothing adult, nothing extremist."],kitHeading:(e,o)=>`${e} YouTubers on Mastodon: ${o} creators to follow`,kitDescription:(e,o)=>`${o} ${e.toLowerCase()} YouTube creators you can follow on Mastodon, with their channels. Follow or subscribe in Mawkingbird, no YouTube account needed.`,kitIntro:e=>`YouTube creators about ${e.toLowerCase()} who also post on Mastodon. Follow their accounts, subscribe to their channels, or both, in one click with Mawkingbird.`,eyebrow:"YouTubers on Mastodon",openKit:"Follow and subscribe in Mawkingbird",noAccount:"No Mastodon account yet? You can still subscribe to the channels and try the kit in your browser.",openApp:"Open the app",lastVideo:"Latest video",videoFeed:"Video feed account",channel:"YouTube channel",moreKits:"More YouTuber kits",allKits:"All YouTuber kits",creators:e=>`${e} creators`,faqTitle:"Questions",faq:[{q:"Do I need a YouTube account?",a:"No. Mawkingbird reads each channel\u2019s public feed, so new videos show up in your subscriptions without signing in to YouTube."},{q:"Who is listed?",a:"Creators whose YouTube channel and Mastodon account point to each other, through their profile, their channel or Wikidata, and who posted or uploaded recently. Some entries are accounts that repost a channel\u2019s videos; they are marked as video feed accounts."},{q:"How do I get listed or removed?",a:"The kits are refreshed regularly from public profiles. If you would rather not be listed, contact Mawkingbird and you will be left out of future refreshes."}],contact:"Ask Mawkingbird on Mastodon",alsoIn:"Also in"},a={hubHeading:"YouTuber auf Mastodon: Creator zum Folgen, nach Thema",hubDescription:"YouTube-Creator auf Mastodon, nach Themen: Folge ihren Mastodon-Konten und abonniere ihre Kan\xE4le \u2013 ganz ohne YouTube-Konto.",hubIntro:["Viele YouTube-Creator posten auch auf Mastodon. Diese Listen ordnen sie nach Themen, jeweils mit Mastodon-Konto und YouTube-Kanal: Du kannst dem einen folgen, das andere abonnieren oder beides.","Aufgenommen wird, wessen YouTube-Kanal und Mastodon-Konto aufeinander verweisen, wer zuletzt aktiv war und wer unsere Regeln erf\xFCllt: nichts f\xFCr Erwachsene, nichts Extremistisches."],kitHeading:(e,o)=>`${e}: ${o} YouTuber auf Mastodon zum Folgen`,kitDescription:(e,o)=>`${o} YouTube-Creator zum Thema ${e}, denen du auf Mastodon folgen kannst \u2013 mit ihren Kan\xE4len. Folgen oder abonnieren in Mawkingbird, ohne YouTube-Konto.`,kitIntro:e=>`YouTube-Creator zum Thema ${e}, die auch auf Mastodon posten. Folge ihren Konten, abonniere ihre Kan\xE4le oder beides \u2013 mit einem Klick in Mawkingbird.`,eyebrow:"YouTuber auf Mastodon",openKit:"In Mawkingbird folgen und abonnieren",noAccount:"Noch kein Mastodon-Konto? Die Kan\xE4le kannst du trotzdem abonnieren und die Liste im Browser ausprobieren.",openApp:"App \xF6ffnen",lastVideo:"Neuestes Video",videoFeed:"Video-Feed-Konto",channel:"YouTube-Kanal",moreKits:"Weitere YouTuber-Listen",allKits:"Alle YouTuber-Listen",creators:e=>`${e} Creator`,faqTitle:"Fragen",faq:[{q:"Brauche ich ein YouTube-Konto?",a:"Nein. Mawkingbird liest den \xF6ffentlichen Feed jedes Kanals, neue Videos erscheinen also in deinen Abos, ohne dass du dich bei YouTube anmeldest."},{q:"Wer steht hier?",a:"Creator, deren YouTube-Kanal und Mastodon-Konto aufeinander verweisen \u2013 \xFCber ihr Profil, ihren Kanal oder Wikidata \u2013 und die zuletzt gepostet oder hochgeladen haben. Einige Eintr\xE4ge sind Konten, die die Videos eines Kanals weiterverbreiten; sie sind als Video-Feed-Konten markiert."},{q:"Wie komme ich auf die Liste oder wieder herunter?",a:"Die Listen werden regelm\xE4\xDFig aus \xF6ffentlichen Profilen erneuert. Wer nicht aufgef\xFChrt werden m\xF6chte, meldet sich bei Mawkingbird und bleibt bei k\xFCnftigen Aktualisierungen au\xDFen vor."}],contact:"Mawkingbird auf Mastodon fragen",alsoIn:"Auch auf"},i={hubHeading:"Youtubeurs sur Mastodon : cr\xE9ateurs \xE0 suivre, par th\xE8me",hubDescription:"Trouvez les cr\xE9ateurs YouTube pr\xE9sents sur Mastodon, par th\xE8me : suivez leurs comptes Mastodon et abonnez-vous \xE0 leurs cha\xEEnes, sans compte YouTube.",hubIntro:["Beaucoup de cr\xE9ateurs YouTube publient aussi sur Mastodon. Ces listes les regroupent par th\xE8me, chacun avec son compte Mastodon et sa cha\xEEne YouTube : suivez l\u2019un, abonnez-vous \xE0 l\u2019autre, ou les deux.","Y figurent les cr\xE9ateurs dont la cha\xEEne YouTube et le compte Mastodon renvoient l\u2019un \xE0 l\u2019autre, actifs r\xE9cemment et conformes \xE0 nos r\xE8gles : rien pour adultes, rien d\u2019extr\xE9miste."],kitHeading:(e,o)=>`${e} : ${o} youtubeurs \xE0 suivre sur Mastodon`,kitDescription:(e,o)=>`${o} cr\xE9ateurs YouTube (${e}) \xE0 suivre sur Mastodon, avec leurs cha\xEEnes. Suivez-les ou abonnez-vous dans Mawkingbird, sans compte YouTube.`,kitIntro:e=>`Des cr\xE9ateurs YouTube du th\xE8me \xAB ${e} \xBB qui publient aussi sur Mastodon. Suivez leurs comptes, abonnez-vous \xE0 leurs cha\xEEnes, ou les deux, en un clic avec Mawkingbird.`,eyebrow:"Youtubeurs sur Mastodon",openKit:"Suivre et s\u2019abonner dans Mawkingbird",noAccount:"Pas encore de compte Mastodon ? Vous pouvez quand m\xEAme vous abonner aux cha\xEEnes et essayer la liste dans votre navigateur.",openApp:"Ouvrir l\u2019application",lastVideo:"Derni\xE8re vid\xE9o",videoFeed:"Compte de flux vid\xE9o",channel:"Cha\xEEne YouTube",moreKits:"Autres listes de youtubeurs",allKits:"Toutes les listes de youtubeurs",creators:e=>`${e} cr\xE9ateurs`,faqTitle:"Questions",faq:[{q:"Faut-il un compte YouTube ?",a:"Non. Mawkingbird lit le flux public de chaque cha\xEEne : les nouvelles vid\xE9os apparaissent dans vos abonnements sans connexion \xE0 YouTube."},{q:"Qui figure ici ?",a:"Des cr\xE9ateurs dont la cha\xEEne YouTube et le compte Mastodon renvoient l\u2019un \xE0 l\u2019autre, par leur profil, leur cha\xEEne ou Wikidata, et qui ont publi\xE9 r\xE9cemment. Certains comptes republient les vid\xE9os d\u2019une cha\xEEne ; ils sont signal\xE9s comme comptes de flux vid\xE9o."},{q:"Comment \xEAtre ajout\xE9 ou retir\xE9 ?",a:"Les listes sont r\xE9guli\xE8rement mises \xE0 jour \xE0 partir des profils publics. Pour ne plus y figurer, contactez Mawkingbird : vous serez exclu des mises \xE0 jour suivantes."}],contact:"Contacter Mawkingbird sur Mastodon",alsoIn:"Aussi en"},t={hubHeading:"YouTubers en Mastodon: creadores para seguir, por tema",hubDescription:"Encuentra creadores de YouTube que est\xE1n en Mastodon, por tema: sigue sus cuentas de Mastodon y suscr\xEDbete a sus canales, sin cuenta de YouTube.",hubIntro:["Muchos creadores de YouTube tambi\xE9n publican en Mastodon. Estas listas los agrupan por tema, cada uno con su cuenta de Mastodon y su canal de YouTube: sigue una, suscr\xEDbete al otro o ambas cosas.","Aparecen los creadores cuyo canal de YouTube y cuenta de Mastodon se enlazan entre s\xED, que han tenido actividad reciente y que cumplen nuestras normas: nada para adultos, nada extremista."],kitHeading:(e,o)=>`${e}: ${o} YouTubers para seguir en Mastodon`,kitDescription:(e,o)=>`${o} creadores de YouTube de ${e.toLowerCase()} que puedes seguir en Mastodon, con sus canales. S\xEDguelos o suscr\xEDbete en Mawkingbird, sin cuenta de YouTube.`,kitIntro:e=>`Creadores de YouTube de ${e.toLowerCase()} que tambi\xE9n publican en Mastodon. Sigue sus cuentas, suscr\xEDbete a sus canales o ambas cosas, con un clic en Mawkingbird.`,eyebrow:"YouTubers en Mastodon",openKit:"Seguir y suscribirse en Mawkingbird",noAccount:"\xBFA\xFAn no tienes cuenta de Mastodon? Puedes suscribirte a los canales y probar la lista en tu navegador.",openApp:"Abrir la app",lastVideo:"\xDAltimo v\xEDdeo",videoFeed:"Cuenta de v\xEDdeos",channel:"Canal de YouTube",moreKits:"M\xE1s listas de YouTubers",allKits:"Todas las listas de YouTubers",creators:e=>`${e} creadores`,faqTitle:"Preguntas",faq:[{q:"\xBFNecesito una cuenta de YouTube?",a:"No. Mawkingbird lee el feed p\xFAblico de cada canal, as\xED que los v\xEDdeos nuevos aparecen en tus suscripciones sin iniciar sesi\xF3n en YouTube."},{q:"\xBFQui\xE9n aparece aqu\xED?",a:"Creadores cuyo canal de YouTube y cuenta de Mastodon se enlazan entre s\xED, por su perfil, su canal o Wikidata, y que han publicado hace poco. Algunas entradas son cuentas que republican los v\xEDdeos de un canal; est\xE1n marcadas como cuentas de v\xEDdeos."},{q:"\xBFC\xF3mo aparecer o dejar de aparecer?",a:"Las listas se actualizan con regularidad a partir de perfiles p\xFAblicos. Si no quieres aparecer, contacta con Mawkingbird y quedar\xE1s fuera de las pr\xF3ximas actualizaciones."}],contact:"Escribir a Mawkingbird en Mastodon",alsoIn:"Tambi\xE9n en"},r={hubHeading:"YouTuber su Mastodon: creator da seguire, per argomento",hubDescription:"Trova i creator di YouTube presenti su Mastodon, per argomento: segui i loro account Mastodon e iscriviti ai loro canali, senza account YouTube.",hubIntro:["Molti creator di YouTube pubblicano anche su Mastodon. Queste liste li raccolgono per argomento, ciascuno con il proprio account Mastodon e il proprio canale YouTube: segui l\u2019uno, iscriviti all\u2019altro, o entrambi.","Sono inclusi i creator il cui canale YouTube e account Mastodon rimandano l\u2019uno all\u2019altro, attivi di recente e conformi alle nostre regole: niente contenuti per adulti, niente estremismi."],kitHeading:(e,o)=>`${e}: ${o} YouTuber da seguire su Mastodon`,kitDescription:(e,o)=>`${o} creator di YouTube (${e}) da seguire su Mastodon, con i loro canali. Seguili o iscriviti in Mawkingbird, senza account YouTube.`,kitIntro:e=>`Creator di YouTube dell\u2019argomento \xAB${e}\xBB che pubblicano anche su Mastodon. Segui i loro account, iscriviti ai loro canali, o entrambi, con un clic in Mawkingbird.`,eyebrow:"YouTuber su Mastodon",openKit:"Segui e iscriviti in Mawkingbird",noAccount:"Non hai ancora un account Mastodon? Puoi comunque iscriverti ai canali e provare la lista nel browser.",openApp:"Apri l\u2019app",lastVideo:"Ultimo video",videoFeed:"Account di video",channel:"Canale YouTube",moreKits:"Altre liste di YouTuber",allKits:"Tutte le liste di YouTuber",creators:e=>`${e} creator`,faqTitle:"Domande",faq:[{q:"Serve un account YouTube?",a:"No. Mawkingbird legge il feed pubblico di ogni canale, quindi i nuovi video compaiono nelle tue iscrizioni senza accedere a YouTube."},{q:"Chi \xE8 in elenco?",a:"Creator il cui canale YouTube e account Mastodon rimandano l\u2019uno all\u2019altro, tramite profilo, canale o Wikidata, e che hanno pubblicato di recente. Alcune voci sono account che ripubblicano i video di un canale; sono indicati come account di video."},{q:"Come entrare o uscire dall\u2019elenco?",a:"Le liste si aggiornano regolarmente dai profili pubblici. Per non comparire, contatta Mawkingbird: sarai escluso dagli aggiornamenti successivi."}],contact:"Scrivere a Mawkingbird su Mastodon",alsoIn:"Anche in"},s={hubHeading:"YouTubers op Mastodon: makers om te volgen, per onderwerp",hubDescription:"Vind YouTube-makers die op Mastodon zitten, per onderwerp: volg hun Mastodon-accounts en abonneer je op hun kanalen, zonder YouTube-account.",hubIntro:["Veel YouTube-makers posten ook op Mastodon. Deze lijsten zetten ze per onderwerp op een rij, elk met hun Mastodon-account en hun YouTube-kanaal: volg het een, abonneer je op het ander, of allebei.","Opgenomen zijn makers van wie het YouTube-kanaal en het Mastodon-account naar elkaar verwijzen, die recent actief waren en die aan onze regels voldoen: niets voor volwassenen, niets extremistisch."],kitHeading:(e,o)=>`${e}: ${o} YouTubers om te volgen op Mastodon`,kitDescription:(e,o)=>`${o} YouTube-makers over ${e.toLowerCase()} die je op Mastodon kunt volgen, met hun kanalen. Volg ze of abonneer je in Mawkingbird, zonder YouTube-account.`,kitIntro:e=>`YouTube-makers over ${e.toLowerCase()} die ook op Mastodon posten. Volg hun accounts, abonneer je op hun kanalen, of allebei, met \xE9\xE9n klik in Mawkingbird.`,eyebrow:"YouTubers op Mastodon",openKit:"Volgen en abonneren in Mawkingbird",noAccount:"Nog geen Mastodon-account? Je kunt je toch op de kanalen abonneren en de lijst in je browser proberen.",openApp:"App openen",lastVideo:"Nieuwste video",videoFeed:"Video-feedaccount",channel:"YouTube-kanaal",moreKits:"Meer YouTuber-lijsten",allKits:"Alle YouTuber-lijsten",creators:e=>`${e} makers`,faqTitle:"Vragen",faq:[{q:"Heb ik een YouTube-account nodig?",a:"Nee. Mawkingbird leest de openbare feed van elk kanaal, dus nieuwe video\u2019s verschijnen in je abonnementen zonder bij YouTube in te loggen."},{q:"Wie staat hier?",a:"Makers van wie het YouTube-kanaal en het Mastodon-account naar elkaar verwijzen, via hun profiel, hun kanaal of Wikidata, en die onlangs iets hebben gepost of ge\xFCpload. Sommige vermeldingen zijn accounts die de video\u2019s van een kanaal doorplaatsen; die staan gemarkeerd als video-feedaccounts."},{q:"Hoe kom ik erop of eraf?",a:"De lijsten worden regelmatig ververst uit openbare profielen. Wie er niet op wil staan, neemt contact op met Mawkingbird en wordt bij volgende verversingen overgeslagen."}],contact:"Mawkingbird op Mastodon vragen",alsoIn:"Ook in"},u={hubHeading:"Mastodon\u306B\u3044\u308BYouTuber\uFF1A\u30C6\u30FC\u30DE\u5225\u306E\u304A\u3059\u3059\u3081\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC",hubDescription:"Mastodon\u306B\u3044\u308BYouTube\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC\u3092\u30C6\u30FC\u30DE\u5225\u306B\u7D39\u4ECB\u3002Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u3092\u30D5\u30A9\u30ED\u30FC\u3057\u3001\u30C1\u30E3\u30F3\u30CD\u30EB\u3092\u767B\u9332\u3067\u304D\u307E\u3059\u3002YouTube\u30A2\u30AB\u30A6\u30F3\u30C8\u306F\u4E0D\u8981\u3067\u3059\u3002",hubIntro:["\u591A\u304F\u306EYouTube\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC\u304CMastodon\u306B\u3082\u6295\u7A3F\u3057\u3066\u3044\u307E\u3059\u3002\u3053\u306E\u30EA\u30B9\u30C8\u3067\u306F\u30C6\u30FC\u30DE\u5225\u306B\u3001Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u3068YouTube\u30C1\u30E3\u30F3\u30CD\u30EB\u306E\u4E21\u65B9\u3092\u7D39\u4ECB\u3057\u3066\u3044\u307E\u3059\u3002\u30D5\u30A9\u30ED\u30FC\u3060\u3051\u3001\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332\u3060\u3051\u3001\u307E\u305F\u306F\u4E21\u65B9\u3082\u53EF\u80FD\u3067\u3059\u3002","\u63B2\u8F09\u3055\u308C\u308B\u306E\u306F\u3001YouTube\u30C1\u30E3\u30F3\u30CD\u30EB\u3068Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u4E92\u3044\u306B\u30EA\u30F3\u30AF\u3057\u3066\u3044\u3066\u3001\u6700\u8FD1\u6D3B\u52D5\u3057\u3066\u304A\u308A\u3001\u63B2\u8F09\u30EB\u30FC\u30EB\uFF08\u30A2\u30C0\u30EB\u30C8\u3084\u904E\u6FC0\u306A\u5185\u5BB9\u306F\u4E0D\u53EF\uFF09\u3092\u6E80\u305F\u3059\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC\u3067\u3059\u3002"],kitHeading:(e,o)=>`${e}\uFF1AMastodon\u3067\u30D5\u30A9\u30ED\u30FC\u3067\u304D\u308BYouTuber ${o}\u4EBA`,kitDescription:(e,o)=>`Mastodon\u3067\u30D5\u30A9\u30ED\u30FC\u3067\u304D\u308B\u300C${e}\u300D\u306EYouTube\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC${o}\u4EBA\u3068\u305D\u306E\u30C1\u30E3\u30F3\u30CD\u30EB\u3002Mawkingbird\u306A\u3089YouTube\u30A2\u30AB\u30A6\u30F3\u30C8\u306A\u3057\u3067\u30D5\u30A9\u30ED\u30FC\u3082\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332\u3082\u3067\u304D\u307E\u3059\u3002`,kitIntro:e=>`Mastodon\u306B\u3082\u6295\u7A3F\u3057\u3066\u3044\u308B\u300C${e}\u300D\u306EYouTube\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC\u3002Mawkingbird\u306A\u3089\u3001\u30A2\u30AB\u30A6\u30F3\u30C8\u306E\u30D5\u30A9\u30ED\u30FC\u3001\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332\u3001\u307E\u305F\u306F\u305D\u306E\u4E21\u65B9\u3092\u30EF\u30F3\u30AF\u30EA\u30C3\u30AF\u3067\u3002`,eyebrow:"Mastodon\u306B\u3044\u308BYouTuber",openKit:"Mawkingbird\u3067\u30D5\u30A9\u30ED\u30FC\u30FB\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332",noAccount:"Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u306A\u304F\u3066\u3082\u3001\u30C1\u30E3\u30F3\u30CD\u30EB\u767B\u9332\u3084\u30D6\u30E9\u30A6\u30B6\u3067\u306E\u304A\u8A66\u3057\u304C\u3067\u304D\u307E\u3059\u3002",openApp:"\u30A2\u30D7\u30EA\u3092\u958B\u304F",lastVideo:"\u6700\u65B0\u52D5\u753B",videoFeed:"\u52D5\u753B\u30D5\u30A3\u30FC\u30C9\u30A2\u30AB\u30A6\u30F3\u30C8",channel:"YouTube\u30C1\u30E3\u30F3\u30CD\u30EB",moreKits:"\u307B\u304B\u306EYouTuber\u30EA\u30B9\u30C8",allKits:"\u3059\u3079\u3066\u306EYouTuber\u30EA\u30B9\u30C8",creators:e=>`${e}\u4EBA`,faqTitle:"\u3088\u304F\u3042\u308B\u8CEA\u554F",faq:[{q:"YouTube\u30A2\u30AB\u30A6\u30F3\u30C8\u306F\u5FC5\u8981\u3067\u3059\u304B\uFF1F",a:"\u3044\u3044\u3048\u3002Mawkingbird\u306F\u5404\u30C1\u30E3\u30F3\u30CD\u30EB\u306E\u516C\u958B\u30D5\u30A3\u30FC\u30C9\u3092\u8AAD\u307F\u8FBC\u3080\u305F\u3081\u3001YouTube\u306B\u30ED\u30B0\u30A4\u30F3\u3057\u306A\u304F\u3066\u3082\u65B0\u3057\u3044\u52D5\u753B\u304C\u767B\u9332\u30C1\u30E3\u30F3\u30CD\u30EB\u306B\u8868\u793A\u3055\u308C\u307E\u3059\u3002"},{q:"\u3069\u3093\u306A\u4EBA\u304C\u63B2\u8F09\u3055\u308C\u3066\u3044\u307E\u3059\u304B\uFF1F",a:"\u30D7\u30ED\u30D5\u30A3\u30FC\u30EB\u3001\u30C1\u30E3\u30F3\u30CD\u30EB\u3001\u307E\u305F\u306FWikidata\u3067YouTube\u30C1\u30E3\u30F3\u30CD\u30EB\u3068Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u4E92\u3044\u306B\u30EA\u30F3\u30AF\u3057\u3066\u3044\u3066\u3001\u6700\u8FD1\u6295\u7A3F\u3084\u30A2\u30C3\u30D7\u30ED\u30FC\u30C9\u3092\u3057\u305F\u30AF\u30EA\u30A8\u30A4\u30BF\u30FC\u3067\u3059\u3002\u30C1\u30E3\u30F3\u30CD\u30EB\u306E\u52D5\u753B\u3092\u8EE2\u8F09\u3059\u308B\u30A2\u30AB\u30A6\u30F3\u30C8\u3082\u4E00\u90E8\u3042\u308A\u3001\u300C\u52D5\u753B\u30D5\u30A3\u30FC\u30C9\u30A2\u30AB\u30A6\u30F3\u30C8\u300D\u3068\u8868\u793A\u3057\u3066\u3044\u307E\u3059\u3002"},{q:"\u63B2\u8F09\u3084\u524A\u9664\u3092\u5E0C\u671B\u3059\u308B\u306B\u306F\uFF1F",a:"\u30EA\u30B9\u30C8\u306F\u516C\u958B\u30D7\u30ED\u30D5\u30A3\u30FC\u30EB\u3092\u3082\u3068\u306B\u5B9A\u671F\u7684\u306B\u66F4\u65B0\u3055\u308C\u307E\u3059\u3002\u63B2\u8F09\u3092\u671B\u307E\u306A\u3044\u5834\u5408\u306FMawkingbird\u306B\u3054\u9023\u7D61\u304F\u3060\u3055\u3044\u3002\u4EE5\u5F8C\u306E\u66F4\u65B0\u3067\u9664\u5916\u3057\u307E\u3059\u3002"}],contact:"Mastodon\u3067Mawkingbird\u306B\u554F\u3044\u5408\u308F\u305B\u308B",alsoIn:"\u307B\u304B\u306E\u8A00\u8A9E"},c={en:n,de:a,fr:i,es:t,it:r,nl:s,ja:u};function l(e){return c[e]??n}export{d as a,c as b,l as c};
